INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7231,1,'psiquiatria','orientacao','Orientações de segurança e adesão em psiquiatria','Orientado paciente e rede de apoio quanto ao uso correto das medicações, risco de interrupção sem supervisão, higiene do sono, redução de álcool e outras substâncias e sinais de alerta para retorno imediato, incluindo piora importante do humor, ideação suicida, agitação intensa, insônia grave ou sintomas psicóticos.','medicação, rede de apoio, higiene do sono, substâncias, sinais de alerta','psiquiatria, orientação, segurança, adesão',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7233,1,'pediatria','anamnese','Anamnese pediátrica para queixa aguda','Paciente pediátrico acompanhado por [responsável], com queixa principal de [queixa], iniciada há [tempo]. Associado a [febre, tosse, vômitos, diarreia, irritabilidade ou outros sintomas]. Alimentação e hidratação em [estado]. Diurese e evacuações [descrição]. Vacinação [em dia, incompleta ou pendente]. Antecedentes relevantes: [alergias, prematuridade, doenças prévias, medicações]. Exame físico direcionado com [achados]. Conduta inicial: [conduta].','responsável, queixa aguda, febre, alimentação, hidratação, vacinação, exame físico, conduta','pediatria, anamnese, urgência leve, consulta infantil',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7235,1,'pediatria','evolucao','Evolução de puericultura e desenvolvimento','Criança em consulta de seguimento, com crescimento em [faixa esperada ou observação], desenvolvimento neuropsicomotor [adequado ou descrição], alimentação [descrição], sono [descrição] e vacinação [situação]. Exame físico sem ou com [achados]. Reforçadas orientações sobre prevenção, rotina, estímulos e retorno em [prazo].','crescimento, desenvolvimento, alimentação, sono, vacinação, exame físico, retorno','pediatria, evolução, puericultura, acompanhamento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7237,1,'pediatria','orientacao','Orientações ao responsável e sinais de alarme pediátricos','Responsável orientado quanto à hidratação frequente, controle de temperatura conforme peso e idade, uso correto das medicações prescritas, manutenção da alimentação conforme tolerância e observação de sinais de alarme. Retornar imediatamente em caso de prostração, dificuldade respiratória, recusa hídrica persistente, convulsão, sonolência excessiva, piora clínica ou febre prolongada.','hidratação, antitérmico, alimentação, dificuldade respiratória, sinais de alarme','pediatria, orientação, responsável, sinais de alarme',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7239,1,'ginecologia_obstetricia','anamnese','Anamnese ginecológica ou obstétrica inicial','Paciente em atendimento de [ginecologia, obstetrícia, pré-natal ou puerpério], com queixa principal de [queixa]. História gineco-obstétrica: DUM [data], G/P/A [descrição], método contraceptivo [descrição], ciclos menstruais [descrição]. Relata [sangramento, corrimento, dor pélvica, movimentação fetal ou outros sintomas]. Antecedentes pessoais e cirúrgicos: [histórico]. Exame físico ou ginecológico com [achados]. Hipótese diagnóstica inicial e plano: [conduta].','tipo de atendimento, DUM, GPA, queixa, sangramento, dor pélvica, exame físico, conduta','ginecologia, obstetrícia, anamnese, pré-natal',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7241,1,'ginecologia_obstetricia','evolucao','Evolução de retorno ginecológico ou pré-natal','Paciente em seguimento, relatando [evolução clínica]. Exames recentes: [descrição]. Mantém ou não [sangramento, corrimento, dor, contrações, movimentação fetal]. Ao exame, apresenta [achados]. Mantidas ou ajustadas orientações, terapêutica e calendário de exames. Próximo retorno programado para [prazo].','evolução clínica, exames recentes, sintomas, exame, terapêutica, calendário de exames, retorno','ginecologia, obstetrícia, evolução, retorno',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7243,1,'ginecologia_obstetricia','orientacao','Orientações e sinais de alerta em ginecologia e obstetrícia','Orientada quanto a uso correto da medicação prescrita, adesão aos exames solicitados, hábitos de vida saudáveis, sinais de alerta e necessidade de retorno precoce. Procurar assistência imediatamente em caso de sangramento importante, perda de líquido, febre, dor intensa, diminuição de movimentos fetais, cefaleia forte, escotomas, piora importante do quadro ou mal-estar persistente.','medicação, exames, hábitos saudáveis, sangramento, perda de líquido, movimentos fetais, sinais de alerta','ginecologia, obstetrícia, orientação, sinais de alerta',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7245,1,'ortopedia_traumatologia','anamnese','Anamnese ortopédica para dor ou trauma','Paciente com queixa principal de [dor ou limitação], localizada em [região anatômica], com lateralidade [direita, esquerda, bilateral]. Início há [tempo], com mecanismo de trauma ou sobrecarga [descrição]. Dor em escala [0 a 10], piora com [fatores] e melhora com [fatores]. Refere limitação funcional em [atividade]. Exame direcionado com [inspeção, amplitude, força, testes especiais, estado neurovascular]. Hipótese inicial e conduta: [conduta].','região anatômica, lateralidade, mecanismo de trauma, escala de dor, limitação funcional, exame físico, conduta','ortopedia, traumatologia, anamnese, dor musculoesquelética',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7247,1,'ortopedia_traumatologia','evolucao','Evolução ortopédica com reavaliação funcional','Paciente em seguimento por [lesão ou dor], relatando evolução [melhora, estabilidade ou piora]. Mantém dor em intensidade [escala], limitação em [atividade] e adesão [descrição] ao tratamento. Exame atual demonstra [amplitude de movimento, edema, força, testes]. Exames complementares: [descrição]. Mantida ou ajustada conduta com [analgesia, imobilização, fisioterapia, infiltração, encaminhamento] e retorno em [prazo].','evolução da dor, limitação, adesão ao tratamento, exame atual, exames complementares, conduta','ortopedia, evolução, reavaliação, funcionalidade',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7249,1,'ortopedia_traumatologia','orientacao','Orientações de proteção articular e retorno ortopédico','Orientado quanto a repouso relativo, uso correto de órtese ou imobilização quando indicada, analgesia conforme prescrição, gelo ou calor conforme fase clínica, progressão segura das atividades e início ou continuidade de reabilitação. Retornar imediatamente em caso de deformidade, piora importante da dor, febre, perda de força, alteração neurovascular distal ou incapacidade funcional acentuada.','repouso relativo, imobilização, analgesia, reabilitação, perda de força, sinais de alarme','ortopedia, orientação, reabilitação, proteção articular',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7251,1,'cardiologia','anamnese','Anamnese cardiológica inicial','Paciente em avaliação cardiológica por [dor torácica, dispneia, palpitações, síncope, hipertensão ou outro motivo]. Fatores de risco: [hipertensão, diabetes, dislipidemia, tabagismo, obesidade, história familiar]. Sintomas iniciados há [tempo], com impacto em [esforço, repouso, sono]. Medicações em uso: [descrição]. Exame físico cardiovascular com [achados], PA [valor], FC [valor]. Exames prévios: [ECG, ECO, MAPA, Holter, laboratoriais]. Hipótese diagnóstica e plano: [conduta].','motivo da consulta, fatores de risco, medicações, exame físico, PA, FC, exames prévios, conduta','cardiologia, anamnese, risco cardiovascular, consulta inicial',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7253,1,'cardiologia','evolucao','Evolução de seguimento cardiológico','Paciente retorna em seguimento por [diagnóstico], com sintomas atuais [descrição]. Refere adesão [boa, parcial ou baixa] às medicações e medidas não farmacológicas. Traz controle domiciliar de pressão ou frequência com [resultados]. Exames recentes mostram [achados]. Mantidas ou ajustadas medicações, metas terapêuticas e plano de reavaliação em [prazo].','diagnóstico, sintomas atuais, adesão, controle pressórico, exames recentes, metas terapêuticas, retorno','cardiologia, evolução, hipertensão, seguimento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7255,1,'cardiologia','orientacao','Orientações de controle cardiovascular domiciliar','Orientado quanto ao uso regular das medicações, redução de sal, controle de peso, prática de atividade física conforme liberação clínica, cessação do tabagismo e monitorização domiciliar de pressão arterial quando indicada. Retornar com exames e diário pressórico. Procurar urgência em caso de dor torácica persistente, dispneia importante, síncope, palpitações intensas ou piora súbita do estado geral.','medicação regular, redução de sal, peso, atividade física, diário pressórico, dor torácica, dispneia','cardiologia, orientação, hipertensão, prevenção',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7257,1,'oftalmologia','anamnese','Anamnese oftalmológica inicial','Paciente com queixa visual principal de [baixa visual, olho vermelho, ardor, secreção, trauma ou outro], acometendo [OD, OE ou OU], iniciada há [tempo]. Relata ou nega [dor ocular, fotofobia, trauma, visão borrada, halos]. Antecedentes oftalmológicos: [cirurgias, uso de óculos, colírios, doenças prévias]. Exame inicial com [acuidade visual, biomicroscopia, tonometria, fundoscopia ou outros achados]. Hipótese e conduta: [conduta].','queixa visual, lateralidade, dor ocular, fotofobia, trauma, antecedentes, acuidade visual, conduta','oftalmologia, anamnese, baixa visual, consulta inicial',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7259,1,'oftalmologia','evolucao','Evolução oftalmológica ambulatorial','Paciente em retorno por [diagnóstico ou queixa], relatando evolução [descrição] após uso de [tratamento]. Acuidade visual atual [descrição]. Exame ocular com [achados]. Exames complementares ou refração: [descrição]. Mantida ou ajustada conduta com [lubrificação, antibiótico, correção óptica, investigação adicional] e retorno em [prazo].','diagnóstico, tratamento, acuidade visual, exame ocular, refração, conduta, retorno','oftalmologia, evolução, retorno, seguimento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7261,1,'oftalmologia','orientacao','Orientações oftalmológicas e sinais de urgência','Orientado quanto ao uso correto dos colírios, higiene ocular, evitar automedicação e manipulação excessiva dos olhos, além de respeitar o retorno programado. Procurar avaliação urgente em caso de perda visual súbita, dor intensa, trauma ocular, secreção importante, fotofobia acentuada, piora rápida dos sintomas ou suspeita de corpo estranho.','colírio, higiene ocular, automedicação, perda visual súbita, dor intensa, trauma ocular','oftalmologia, orientação, colírio, urgência',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7263,1,'neurologia','anamnese','Anamnese neurológica inicial','Paciente em avaliação neurológica por [cefaleia, tontura, parestesia, crise, tremor, déficit motor, alteração de memória ou outro sintoma]. Início há [tempo], frequência [descrição] e fatores desencadeantes [descrição]. Sintomas associados: [náuseas, aura, alteração visual, fraqueza, dormência, alteração da fala]. Antecedentes relevantes e medicações em uso: [descrição]. Exame neurológico com [achados]. Hipótese diagnóstica inicial e plano de investigação ou tratamento: [conduta].','sintoma neurológico, início, frequência, gatilhos, sintomas associados, exame neurológico, conduta','neurologia, anamnese, cefaleia, consulta inicial',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7265,1,'neurologia','evolucao','Evolução neurológica de seguimento','Paciente retorna em seguimento por [diagnóstico ou síndrome], referindo evolução [melhora, estabilidade ou piora] dos sintomas. Mantém episódios de [cefaleia, crise, tontura, parestesia ou outro] com frequência [descrição]. Exames recentes: [RM, TC, EEG, ENMG ou outros]. Exame neurológico atual com [achados]. Mantido ou ajustado plano terapêutico, orientações e reavaliação em [prazo].','diagnóstico, evolução dos sintomas, frequência, exames recentes, exame neurológico, plano terapêutico','neurologia, evolução, seguimento, retorno',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7267,1,'neurologia','orientacao','Orientações neurológicas e sinais de alarme','Orientado quanto ao uso correto das medicações, manutenção de diário de sintomas quando aplicável, cuidados com sono, hidratação e gatilhos individuais. Procurar atendimento imediato em caso de déficit neurológico súbito, alteração de fala, convulsão prolongada, cefaleia explosiva, rebaixamento do nível de consciência, febre associada a rigidez de nuca ou piora abrupta do quadro.','medicação, diário de sintomas, sono, hidratação, déficit neurológico súbito, cefaleia explosiva','neurologia, orientação, sinais de alarme, crise',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7291,1,'medico','evolucao','Evolução clínica geral de seguimento','Motivo do acompanhamento: [descrição]. Evolução desde a última consulta: [relato]. Adesão e efeitos adversos: [avaliação]. Exame físico e resultados disponíveis: [achados]. Avaliação dos problemas ativos: [descrição]. Conduta discutida: [plano]. Orientações e retorno: [registro].','evolução, problemas ativos, adesão, exame físico, resultados, conduta, retorno','clínica médica, evolução, acompanhamento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7293,1,'medico','orientacao','Orientações clínicas gerais individualizadas','Plano acordado com o paciente: [descrição]. Registrar orientações efetivamente fornecidas sobre [uso de medicamentos prescritos, autocuidado e acompanhamento]. Sinais de alerta específicos do caso e local de atendimento: [descrição]. Exames e retorno: [prazos]. Dúvidas e compreensão do paciente: [registro].','plano, autocuidado, medicamentos, sinais de alerta, retorno, compreensão','clínica médica, orientação, autocuidado',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
