INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7299,1,'dentista','orientacao','Orientações odontológicas individualizadas','Atendimento ou procedimento realizado: [descrição]. Orientações individualizadas de higiene oral, alimentação e cuidados locais: [registro]. Medicamentos apenas conforme prescrição emitida: [registro]. Sinais de alerta e canal para intercorrências: [descrição]. Revisão e continuidade do tratamento: [prazo e plano].','procedimento, higiene oral, cuidados locais, prescrição, sinais de alerta, revisão','odontologia, orientação, acompanhamento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7301,1,'psicologia','anamnese','Entrevista psicológica inicial','Demanda e objetivos relatados: [descrição]. História e contexto da demanda: [registro]. Contexto familiar, social e ocupacional relevante: [descrição]. Acompanhamentos anteriores e atuais: [registro]. Observações clínicas: [descrição]. Avaliação de riscos e fatores de proteção, quando pertinente: [registro]. Contrato terapêutico, limites de sigilo e plano inicial: [registro].','demanda, contexto, histórico, observações, riscos, fatores de proteção, plano','psicologia, entrevista inicial, acolhimento',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
