INSERT INTO `modelos_clinicos` (`id`,`empresa_id`,`tema`,`tipo_documento`,`titulo`,`conteudo`,`campos_chave`,`tags`,`ativo`,`criado_por`,`atualizado_por`,`criado_em`,`atualizado_em`) VALUES (7305,1,'psicologia','orientacao','Orientações e continuidade do cuidado psicológico','Orientações discutidas na sessão: [descrição]. Estratégias acordadas e atividades, quando pertinentes: [registro]. Rede de apoio e encaminhamentos pactuados: [descrição]. Plano de segurança, se indicado pela avaliação: [registro]. Em situação de risco imediato, buscar serviço de urgência. Continuidade do acompanhamento: [prazo].','orientações, estratégias, rede de apoio, encaminhamentos, segurança, retorno','psicologia, orientação, continuidade do cuidado',1,NULL,NULL,'2026-11-11 23:52:13','2026-11-11 23:52:13');
